import type { ConfigFieldDefinition, ConfigFieldType, ConfigSource } from '../src/index.ts'

import { mkdtempSync, rmSync, writeFileSync } from 'node:fs'
import { mkdir } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { dirname, join } from 'node:path'

import { createConfigSource } from '../src/index.ts'

/** A field definition as generated by the compiler (env / key derived from the property). */
export function field(
  property: string,
  type: ConfigFieldType = 'string',
  extra: Partial<ConfigFieldDefinition> = {},
): ConfigFieldDefinition {
  return {
    property,
    env: property.replace(/([a-z0-9])([A-Z])/g, '$1_$2').toUpperCase(),
    key: property,
    type,
    required: true,
    secret: false,
    ...extra,
  }
}

/** A source with a single layer. */
export function source(values: Record<string, unknown>, origin = 'test'): ConfigSource {
  return createConfigSource([{ origin, values }])
}

/** Creates a temporary directory with `files` (relative paths → content). */
export async function tempDir(files: Record<string, string> = {}): Promise<{ dir: string; cleanup(): void }> {
  const dir = mkdtempSync(join(tmpdir(), 'znight-config-'))
  for (const [path, content] of Object.entries(files)) {
    const file = join(dir, path)
    await mkdir(dirname(file), { recursive: true })
    writeFileSync(file, content)
  }
  return { dir, cleanup: () => rmSync(dir, { recursive: true, force: true }) }
}

/** Runs `fn` and returns what it threw (fails when it does not throw). */
export async function caught(fn: () => unknown): Promise<Error> {
  try {
    await fn()
  } catch (error) {
    return error as Error
  }
  throw new Error('expected the function to throw')
}
